   "content": "{\n  \"source\": \"《庆余年》\",\n  \"segment\": \"第一卷·第12章（首个大高潮章·示范）\",\n  \"structure\": {\n    \"起\": \"范闲入京前夕，暗流已动（铺垫信息差）\",\n    \"承\": \"各方势力试探，主角以静制动\",\n    \"转\": \"一封信揭出身份疑云，棋局骤紧\",\n    \"合\": \"主角轻描淡写落一子，对手措手不及\"\n  },\n  \"character_moves\": [\n    \"主角动作：不直接接招，用一句闲笔反问把球踢回（算计/留后手的具体描写）\",\n    \"对手反应：被将一军后仍维持体面，未被降智（有来有回）\"\n  ],\n  \"hook\": \"章末钩子：'那封信，原是写给死人的。'（留白式钩子，不说破）\",\n  \"tension\": \"高\",\n  \"reusable_skill\": \"用一句闲笔反问代替正面回应，既留后手又显从容——可迁移到毒士'引而不发'铁律\"\n}",
